// Assemble the Bureau of Bad Ideas theme (6 Divi 5 pages for a loud little creative agency) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language bold-vibrant + the neo-brutal style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php bureau      -> dist/theme-packs/bureau/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && BBI_DIR=<dir with the six json files> npx tsx scripts/create-bureau-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.BBI_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/bureau';

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: 'Bureau of Bad Ideas',
  tagline: 'Bad ideas, professionally supervised.',
  audience: 'founders, marketing leads and small-business owners who want a brand, campaign or website with a point of view, from a studio that argues with the brief before it designs anything',
  conversionGoal: 'submit a brief',
  primaryCta: 'Submit a brief',
  accentColorHex: '#2438FF',
  voice: 'deadpan, funny and plain-spoken. Short sentences, bureaucratic gags kept light, concrete numbers, no agency jargon.',
  palette: { primary: '#2438ff', secondary: '#3d3d52', tint: '#ffd60a', dark: '#0c0c14', heading: '#0c0c14', body: '#3d3d52' },
  designNotes: 'Bold-vibrant design language with the neo-brutal kit: saturated yellow and cobalt blocks, black text, very heavy Unbounded headlines, Work Sans body, 3px frames and hard offset shadows.',
};

const BRAND_FACTS =
  'Bureau of Bad Ideas, 1217 West Fulton Street, Chicago, IL 60607. Phone (312) 555-0188. hello@badideas.studio. ' +
  'Sample copy: names, prices and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'work', roleLabel: 'Case Files' },
  { role: 'services', roleLabel: 'Departments' },
  { role: 'process', roleLabel: 'Process' },
  { role: 'about', roleLabel: 'The Bureau' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'creative_agency', style: 'bold', color: 'yellow', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'bureau-creative-agency-theme';
const PACK_TITLE = 'Bureau of Bad Ideas: Creative Agency Theme (6 Pages)';
const DESCRIPTION =
  'A complete six-page Divi 5 website for a creative agency, branding studio, design collective or any loud little ' +
  'business that wants to stand out, ready to make your own. Home, Case Files, Departments, Process, The Bureau and ' +
  'Contact share one unmistakable identity: saturated yellow, cobalt blocks, heavy Unbounded headlines, hard 3px frames ' +
  'and offset shadows that lift on hover. The copy plays a deadpan bureaucracy gag (filing cabinets, house rules, a ' +
  'worst-idea workshop), so the pack is as fun to read as it is to look at. Every section is built from proven, ' +
  'validated recipes and a single design language and style kit, so buttons, accordions, forms and type match on every ' +
  'page, on desktop, tablet and phone. A big typographic hero, an annual-report figures band, a departments bento, ' +
  'a case-file portfolio, a before-and-after slider, a zigzag of featured cases, retainer pricing, a method page with a ' +
  'timeline and a head-to-head comparison, a team page with a founder note, FAQs and a contact form are all in place. ' +
  'Names, prices, results and reviews are sample copy: swap in your own and publish. No lorem ipsum, no broken layouts. ' +
  'One simple commercial license, unlimited client sites.';
const PACK_SEO = {
  metaTitle: 'Bureau of Bad Ideas: Creative Agency Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A complete six-page bold Divi 5 website theme for a creative agency or branding studio: Home, Case Files, ' +
    'Departments, Process, About and Contact. Loud yellow and cobalt, real copy, portfolio, pricing and a funny voice.',
  keywords: [
    'divi 5 agency theme', 'creative agency website template', 'branding studio divi 5 theme', 'bold divi template',
    'design studio website template', 'divi 5 multi-page theme',
  ],
};
const PRICE_CENTS = 1200;

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Bureau pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
